int check(){return 1;}
D step(D x,int i){return x*__builtin_complex(0.0,1.0)+double(i%7-3);}
template<class T> T roundtrip(T x){try{throw x;}catch(const T& y){return y;}}
int main(int argc,char**argv){if(!check())return 2;
D x=__builtin_complex(double(argc>1?argv[1][0]-'0':1),0.0);long r=0,s=0;
for(int i=0;i<2000000;++i){x=step(x,i);if(i%100==0)x=roundtrip(x);r+=long(__real__ x);s+=long(__imag__ x);}
return r==-5&&s==1&&__real__ x==1&&__imag__ x==1?0:1;}

